import java.lang.management.ManagementFactory;
import java.lang.management.MemoryPoolMXBean;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class Main {
    static long runtimeUsed() {
        Runtime rt = Runtime.getRuntime();
        return rt.totalMemory() - rt.freeMemory();
    }

    public static void main(String[] args) {
        Set<String> pools = ManagementFactory.getMemoryPoolMXBeans().stream()
            .map(MemoryPoolMXBean::getName)
            .collect(Collectors.toSet());

        long before = runtimeUsed();
        List<byte[]> liveObjects = new ArrayList<>();
        for (int i = 0; i < 8; i++) {
            liveObjects.add(new byte[512 * 1024]);
        }
        long after = runtimeUsed();

        boolean hasYoungPool = pools.stream().anyMatch(name -> name.contains("Eden") || name.contains("Survivor") || name.contains("Young"));
        boolean hasOldPool = pools.stream().anyMatch(name -> name.contains("Old") || name.contains("Tenured"));

        System.out.println("heap pools: " + pools);
        System.out.println("runtime used before/after: " + before + " -> " + after);
        System.out.println("live arrays: " + liveObjects.size() + ", bytes kept: " + liveObjects.stream().mapToInt(a -> a.length).sum());

        assert liveObjects.size() == 8;
        assert liveObjects.stream().mapToInt(a -> a.length).sum() == 4 * 1024 * 1024;
        assert after > before;
        assert hasYoungPool;
        assert hasOldPool;
    }
}
